// ---- services/pr-review/src/task-event.js ----
const STATUS = {
  NOT_STARTED: "Not started",
  IN_PROGRESS: "In Progress",
  READY: "Ready for Review",
  DONE: "Done",
};

const STATUS_KEYS = {
  "not started": STATUS.NOT_STARTED,
  "in progress": STATUS.IN_PROGRESS,
  "ready for review": STATUS.READY,
  done: STATUS.DONE,
};

const normalizeStatus = (s) => STATUS_KEYS[String(s ?? "").trim().toLowerCase().replace(/\s+/g, " ")] ?? null;

// body: { secret, spreadsheet, sheet, row, title, taskUrl, status, previousStatus }
function parseTaskEvent(body, env) {
  if (!env.MF_TASKS_SECRET || body?.secret !== env.MF_TASKS_SECRET) return { error: "bad secret" };
  const status = normalizeStatus(body.status);
  if (!status) return { ignore: `unknown status "${body.status}"` };
  const previous = normalizeStatus(body.previousStatus);
  const task = {
    title: String(body.title ?? "").trim() || "Untitled task",
    url: String(body.taskUrl ?? "").trim() || null,
    sheet: body.sheet ?? null,
    row: body.row ?? null,
  };
  const action = previous === STATUS.IN_PROGRESS && status === STATUS.READY ? "publish" : "status";
  return { action, task, status, previous };
}

// ---- services/pr-review/src/pr-card.js ----


const CARD_COLOR = 0x2f81f7;
const WARN_COLOR = 0xd29922;

// one card per task; the id is stable across re-publishing and Resend
function cardIdFor(taskUrl) {
  const ref = parseGithubUrl(taskUrl);
  return ref ? `${ref.owner}__${ref.repo}__${ref.kind}-${ref.number}`.toLowerCase() : null;
}

// roles from PR labels, then task labels, then the default roles from settings
function rolesForPr(prLabels, taskLabels, settings) {
  const map = Object.fromEntries(Object.entries(settings.pr.labelRoles ?? {}).map(([k, v]) => [k.toLowerCase(), v]));
  const pick = (labels) => [...new Set((labels ?? []).map((l) => map[String(l).toLowerCase()]).filter(Boolean))];
  const fromPr = pick(prLabels);
  if (fromPr.length) return fromPr;
  const fromTask = pick(taskLabels);
  if (fromTask.length) return fromTask;
  return [...(settings.pr.defaultRoleIds ?? [])];
}

const resendId = (cardId) => `pr:resend:${cardId}`;

function cardButtons(task, pr, cardId, resendEnabled) {
  return [row(
    task.url ? linkButton("Open task", task.url) : null,
    actionButton("Resend", resendId(cardId), { disabled: !resendEnabled }),
    linkButton("Open PR", pr.url),
  )];
}

function buildPrCard({ pr, task, roleIds, cardId, resendEnabled = false }) {
  const mentions = roleIds.map(roleMention).join(" ");
  const fields = [{ name: "Task", value: task.url ? `[${task.title}](${task.url})`.slice(0, 1024) : task.title.slice(0, 1024) }];
  return {
    content: `${mentions ? mentions + " " : ""}**${pr.author.login}** opened a PR for review: ${pr.title}`.slice(0, 2000),
    embeds: [{
      author: { name: pr.author.login, ...(pr.author.avatarUrl ? { icon_url: pr.author.avatarUrl } : {}), ...(pr.author.url ? { url: pr.author.url } : {}) },
      title: `#${pr.number} ${pr.title}`.slice(0, 256),
      url: pr.url,
      description: "```diff\n+ " + pr.additions + " additions\n- " + pr.deletions + " deletions\n```",
      fields,
      footer: { text: `${pr.owner}/${pr.repo}` },
      color: CARD_COLOR,
    }],
    components: cardButtons(task, pr, cardId, resendEnabled),
    allowed_mentions: { parse: [], roles: roleIds },
  };
}

function buildUnlinkedMessage(task) {
  const text = task.url
    ? `⚠️ Task "${task.title}" is in Ready for Review, but no PR is linked to it.`
    : `⚠️ Task "${task.title}" is in Ready for Review, but it has no link to a GitHub issue.`;
  return {
    content: text.slice(0, 2000),
    embeds: [{ description: "Add `Closes #<issue>` to the PR description, then move the task to In Progress and back to Ready for Review.", color: WARN_COLOR }],
    components: task.url ? [row(linkButton("Open task", task.url))] : [],
    allowed_mentions: { parse: [] },
  };
}

// ---- services/pr-review/src/pr-state.js ----

function evaluateCard(card, pr, now, settings) {
  const e = settings.pr.emojis;
  if (!pr) return { state: "MISSING", reaction: card.reaction ?? null, resendEnabled: false, active: false, reason: "the PR was not found" };
  if (pr.state === "MERGED") return { state: "MERGED", reaction: e.merged, resendEnabled: false, active: false, reason: "the PR is merged" };
  if (pr.state === "CLOSED") return { state: "CLOSED", reaction: null, resendEnabled: false, active: false, reason: "the PR is closed" };

  const reviewState = pr.reviewDecision === "APPROVED" ? "APPROVED" : pr.reviewDecision === "CHANGES_REQUESTED" ? "CHANGES_REQUESTED" : "WAITING";
  const reaction = reviewState === "APPROVED" ? e.approved : reviewState === "CHANGES_REQUESTED" ? e.changesRequested : null;

  if (card.taskStatus && card.taskStatus !== STATUS.READY)
    return { state: reviewState, reaction, resendEnabled: false, active: false, reason: `the task is ${card.taskStatus}` };
  if (reviewState === "APPROVED") return { state: reviewState, reaction, resendEnabled: false, active: true, reason: "the PR is approved" };
  if (reviewState === "CHANGES_REQUESTED") return { state: reviewState, reaction, resendEnabled: false, active: true, reason: "changes are requested" };

  const hours = (new Date(now) - new Date(card.publishedAt)) / 36e5;
  const ready = hours >= settings.pr.resendAfterHours;
  return {
    state: reviewState, reaction: null, resendEnabled: ready, active: true,
    reason: ready ? null : `Resend becomes available ${settings.pr.resendAfterHours} hours after publishing`,
  };
}

// ---- services/pr-review/src/pr-service.js ----








const services = (ctx) => ({ fs: createFirestore(ctx), discord: createDiscord(ctx), gh: createGithub(ctx) });

async function safeDelete(discord, channelId, messageId) {
  try {
    await discord.deleteMessage(channelId, messageId);
    return true;
  } catch (e) {
    return e.statusCode === 404;
  }
}

async function handleTaskEvent(ctx, body) {
  const ev = parseTaskEvent(body, ctx.env);
  if (ev.error || ev.ignore) return { result: ev.error ?? ev.ignore };
  const { fs, discord, gh } = services(ctx);
  const cardId = cardIdFor(ev.task.url);

  if (ev.action === "status") {
    if (!cardId) return { result: "status change of a task without a GitHub link" };
    const card = await fs.get(`pr_cards/${cardId}`);
    if (!card?.active) return { result: "no active card" };
    const patch = { taskStatus: ev.status, updatedAt: ctx.now };
    if (ev.status !== STATUS.READY) {
      patch.active = false;
      patch.resendEnabled = false;
      if (card.resendEnabled)
        await discord.editMessage(card.channelId, card.messageId, { components: cardButtons(card.task, card.pr, cardId, false) }).catch(() => {});
    }
    await fs.update(`pr_cards/${cardId}`, patch);
    return { result: `card ${cardId}: task status ${ev.status}` };
  }

  const settings = await loadSettings(fs, ctx.env);
  const channelId = settings.channels.prReview;
  if (!channelId) throw new Error("PR review channel is not configured (settings.channels.prReview)");

  const found = cardId ? await gh.findPrForTask(ev.task.url) : { pr: null, issue: null };
  if (!found.pr) {
    await discord.postMessage(channelId, buildUnlinkedMessage(ev.task));
    await logEvent(fs, "pr-review", "pr_unlinked", { taskUrl: ev.task.url, taskTitle: ev.task.title }, ctx.now);
    return { result: "task has no linked PR" };
  }

  const pr = found.pr;
  const task = { ...ev.task, title: ev.task.title || found.issue?.title };
  const roleIds = rolesForPr(pr.labels, found.issue?.labels, settings);

  const previous = await fs.get(`pr_cards/${cardId}`);
  if (previous?.active && previous.messageId) await safeDelete(discord, previous.channelId, previous.messageId);

  const message = await discord.postMessage(channelId, buildPrCard({ pr, task, roleIds, cardId }));
  await fs.set(`pr_cards/${cardId}`, {
    task,
    taskStatus: ev.status,
    pr: { owner: pr.owner, repo: pr.repo, number: pr.number, url: pr.url, title: pr.title, author: pr.author.login },
    roleIds,
    channelId,
    messageId: message.id,
    publishedAt: ctx.now,
    state: "WAITING",
    reaction: null,
    resendEnabled: false,
    resendCount: previous?.resendCount ?? 0,
    active: true,
    updatedAt: ctx.now,
  });
  await logEvent(fs, "pr-review", "pr_published", { cardId, pr: pr.url, author: pr.author.login, roleIds }, ctx.now);
  return { result: `published ${cardId}` };
}

async function checkCards(ctx) {
  const { fs, discord, gh } = services(ctx);
  const settings = await loadSettings(fs, ctx.env);
  const cards = await fs.query("pr_cards", [["active", "==", true]]);
  const report = [];
  for (const card of cards) {
    try {
      const pr = await gh.getPr(card.pr.owner, card.pr.repo, card.pr.number);
      const next = evaluateCard(card, pr, ctx.now, settings);
      if (next.reaction !== card.reaction) {
        if (card.reaction) await discord.removeOwnReaction(card.channelId, card.messageId, card.reaction).catch(() => {});
        if (next.reaction) await discord.addReaction(card.channelId, card.messageId, next.reaction);
      }
      if (next.resendEnabled !== !!card.resendEnabled)
        await discord.editMessage(card.channelId, card.messageId, { components: cardButtons(card.task, card.pr, card.id, next.resendEnabled) });
      await fs.update(`pr_cards/${card.id}`, {
        state: next.state, reaction: next.reaction, resendEnabled: next.resendEnabled, active: next.active, checkedAt: ctx.now,
      });
      if (next.state !== card.state) await logEvent(fs, "pr-review", "pr_state_changed", { cardId: card.id, from: card.state, to: next.state }, ctx.now);
      report.push(`${card.id}: ${next.state}${next.resendEnabled ? ", resend" : ""}${next.active ? "" : ", done"}`);
    } catch (e) {
      report.push(`${card.id}: error ${e.message}`);
    }
  }
  return { checked: cards.length, report };
}

// Phase 1: answer Discord within 3 s with a deferred ephemeral reply.
function prInteractionResponse(body) {
  const [, action] = String(body.data?.custom_id ?? "").split(":");
  if (action !== "resend") return { response: ephemeral("Unknown action."), work: false };
  return { response: { type: ResponseType.DEFERRED_MESSAGE, data: { flags: EPHEMERAL } }, work: true };
}

// Phase 2: re-check and re-publish, then edit the deferred reply.
async function resendCard(ctx, body) {
  const { fs, discord, gh } = services(ctx);
  const cardId = String(body.data.custom_id).split(":").slice(2).join(":");
  const reply = (content) => discord.editOriginalResponse(body.token, { content });

  const card = await fs.get(`pr_cards/${cardId}`);
  if (!card?.active) return reply("This card is no longer active.");
  const settings = await loadSettings(fs, ctx.env);
  const pr = await gh.getPr(card.pr.owner, card.pr.repo, card.pr.number);
  const state = evaluateCard(card, pr, ctx.now, settings);
  if (!state.resendEnabled) return reply(`Resend is not available: ${state.reason}.`);

  const roleIds = rolesForPr(pr.labels, [], settings);
  const message = await discord.postMessage(card.channelId, buildPrCard({ pr, task: card.task, roleIds: roleIds.length ? roleIds : card.roleIds, cardId }));
  const deleted = await safeDelete(discord, card.channelId, card.messageId);
  if (!deleted)
    await discord.editMessage(card.channelId, card.messageId, { components: cardButtons(card.task, card.pr, cardId, false) }).catch(() => {});
  await fs.update(`pr_cards/${cardId}`, {
    messageId: message.id, publishedAt: ctx.now, resendEnabled: false, reaction: null, state: "WAITING",
    resendCount: (card.resendCount ?? 0) + 1, updatedAt: ctx.now,
  });
  await logEvent(fs, "pr-review", "pr_resent", { cardId, by: body.member?.user?.id ?? body.user?.id ?? null }, ctx.now);
  return reply("Resent ✅");
}


